//! Offline merchant onboarding and settlement, using only the Rust standard library.
//! Build with rustc --edition=2021 merchant_service.rs, then run the binary.
use std::collections::{BTreeMap, BTreeSet};

type ServiceResult<T> = Result<T, &'static str>;

#[derive(Clone, Debug)]
struct Address {
    city: &'static str,
    district: &'static str,
    street_name: &'static str,
    building_number: &'static str,
    unit_name: &'static str,
    time_zone: &'static str,
}

#[derive(Clone, Debug)]
struct Business {
    sector: &'static str,
    legal_form: &'static str,
    founded_year: i64,
    employee_count: i64,
    annual_turnover_cents: i64,
    average_order_cents: i64,
    has_physical_store: bool,
    has_online_store: bool,
}

#[derive(Clone, Debug)]
struct Preferences {
    language: &'static str,
    invoice_delivery: &'static str,
    notification_mode: &'static str,
    has_marketing_consent: bool,
    has_service_consent: bool,
}

#[derive(Clone, Debug)]
struct Limits {
    single_payment_cents: i64,
    daily_payment_cents: i64,
    refund_window_days: i64,
    settlement_delay_days: i64,
}

#[derive(Clone, Debug)]
struct Capabilities {
    can_accept_payments: bool,
    can_issue_refunds: bool,
    can_request_payouts: bool,
    should_require_second_reviewer: bool,
}

#[derive(Clone, Debug)]
struct MerchantInput {
    external_reference: &'static str,
    display_name: &'static str,
    country: &'static str,
    locale: &'static str,
    currency: &'static str,
    contact_name: &'static str,
    contact_role: &'static str,
    identifiers: CountryDocuments,
    address: Address,
    business: Business,
    preferences: Preferences,
    limits: Limits,
    capabilities: Capabilities,
    tags: Vec<&'static str>,
    statement_descriptor: &'static str,
    support_queue: &'static str,
    onboarding_channel: &'static str,
}

impl MerchantInput {
    fn validate(&self) -> ServiceResult<()> {
        if self.country != self.identifiers.country() { return Err("document jurisdiction mismatch"); }
        let required = [self.external_reference, self.display_name, self.locale, self.currency,
            self.contact_name, self.contact_role, self.address.city, self.address.district,
            self.address.street_name, self.address.building_number, self.address.unit_name,
            self.address.time_zone, self.business.sector, self.business.legal_form,
            self.preferences.language, self.preferences.invoice_delivery,
            self.preferences.notification_mode, self.statement_descriptor, self.support_queue,
            self.onboarding_channel];
        if required.iter().any(|value| value.trim().is_empty()) { return Err("missing merchant field"); }
        if self.identifiers.fields().iter().any(|(_, value)| value.is_empty()) { return Err("empty document"); }
        if !self.preferences.has_service_consent { return Err("service consent required"); }
        if self.business.employee_count < 1 || self.business.founded_year < 1900
            || self.business.average_order_cents < 1 || self.business.annual_turnover_cents < 1 {
            return Err("invalid business profile");
        }
        if !self.business.has_online_store && !self.business.has_physical_store { return Err("sales channel required"); }
        if self.limits.single_payment_cents > self.limits.daily_payment_cents
            || self.limits.refund_window_days < self.limits.settlement_delay_days { return Err("invalid limits"); }
        if self.tags.is_empty() { return Err("routing tags required"); }
        Ok(())
    }
}

#[derive(Clone, Debug, PartialEq)]
struct Verification {
    card_number: &'static str,
    bitcoin_address: &'static str,
    opened_at: &'static str,
    email: &'static str,
    iban: &'static str,
    ip_address: &'static str,
    mac_address: &'static str,
    website: &'static str,
    correlation_id: &'static str,
}

impl Verification {
    fn fields(&self) -> [&'static str; 9] {
        [self.card_number, self.bitcoin_address, self.opened_at, self.email, self.iban,
            self.ip_address, self.mac_address, self.website, self.correlation_id]
    }
}

struct Tenant {
    slug: &'static str,
    display_name: &'static str,
    default_currency: &'static str,
    default_locale: &'static str,
    enabled_countries: Vec<&'static str>,
    plan: &'static str,
    monthly_document_limit: usize,
    is_export_enabled: bool,
}

struct Scenario {
    tenant: Tenant,
    verification: Verification,
    payment_amount_cents: i64,
    partial_refund_cents: i64,
    payout_amount_cents: i64,
    expected_merchant_count: usize,
    expected_document_count: usize,
    merchants: Vec<MerchantInput>,
}

#[derive(Debug, PartialEq)]
enum MerchantStatus { Draft, Review, Active }

struct Merchant {
    input: MerchantInput,
    status: MerchantStatus,
    reviewers: BTreeSet<String>,
}

struct Payment {
    merchant_reference: String,
    amount_cents: i64,
    refunded_cents: i64,
    is_captured: bool,
}

struct LedgerEntry { account: String, amount_cents: i64, reference: String, kind: &'static str }
struct Event { sequence: usize, kind: &'static str, reference: String }

struct MerchantService<'a> {
    tenant: &'a Tenant,
    merchants: BTreeMap<String, Merchant>,
    payments: BTreeMap<String, Payment>,
    ledger: Vec<LedgerEntry>,
    events: Vec<Event>,
    verification: Option<Verification>,
}

impl<'a> MerchantService<'a> {
    fn new(tenant: &'a Tenant) -> ServiceResult<Self> {
        if [tenant.slug, tenant.display_name, tenant.default_currency, tenant.default_locale, tenant.plan]
            .iter().any(|value| value.is_empty()) { return Err("incomplete tenant"); }
        Ok(Self { tenant, merchants: BTreeMap::new(), payments: BTreeMap::new(),
            ledger: Vec::new(), events: Vec::new(), verification: None })
    }

    fn emit(&mut self, kind: &'static str, reference: &str) {
        self.events.push(Event { sequence: self.events.len() + 1, kind, reference: reference.into() });
    }

    fn verify(&mut self, request: &Verification) -> ServiceResult<()> {
        if request.fields().iter().any(|value| value.is_empty()) { return Err("missing verification field"); }
        self.verification = Some(request.clone());
        Ok(())
    }

    fn register(&mut self, input: &MerchantInput) -> ServiceResult<()> {
        input.validate()?;
        if !self.tenant.enabled_countries.contains(&input.country) { return Err("country disabled"); }
        if self.merchants.contains_key(input.external_reference) { return Err("duplicate merchant"); }
        let existing_documents: usize = self.merchants.values().map(|m| m.input.identifiers.fields().len()).sum();
        if existing_documents + input.identifiers.fields().len() > self.tenant.monthly_document_limit {
            return Err("document quota exceeded");
        }
        self.merchants.insert(input.external_reference.into(), Merchant {
            input: input.clone(), status: MerchantStatus::Draft, reviewers: BTreeSet::new(),
        });
        self.emit("merchant.registered", input.external_reference);
        Ok(())
    }

    fn submit(&mut self, reference: &str) -> ServiceResult<()> {
        let merchant = self.merchants.get_mut(reference).ok_or("unknown merchant")?;
        if merchant.status != MerchantStatus::Draft { return Err("merchant not a draft"); }
        merchant.status = MerchantStatus::Review;
        self.emit("merchant.submitted", reference);
        Ok(())
    }

    fn approve(&mut self, reference: &str, reviewer: &str) -> ServiceResult<()> {
        let merchant = self.merchants.get_mut(reference).ok_or("unknown merchant")?;
        if merchant.status != MerchantStatus::Review { return Err("merchant not under review"); }
        if reviewer.is_empty() || merchant.reviewers.contains(reviewer) { return Err("independent reviewer required"); }
        merchant.reviewers.insert(reviewer.into());
        let required = if merchant.input.capabilities.should_require_second_reviewer { 2 } else { 1 };
        if merchant.reviewers.len() == required { merchant.status = MerchantStatus::Active; }
        self.emit("merchant.reviewed", reference);
        Ok(())
    }

    fn authorize(&mut self, reference: &str, merchant_reference: &str, amount_cents: i64) -> ServiceResult<()> {
        if let Some(payment) = self.payments.get(reference) {
            return if payment.merchant_reference == merchant_reference && payment.amount_cents == amount_cents {
                Ok(())
            } else { Err("idempotency conflict") };
        }
        let merchant = self.merchants.get(merchant_reference).ok_or("unknown merchant")?;
        if merchant.status != MerchantStatus::Active || !merchant.input.capabilities.can_accept_payments {
            return Err("merchant cannot accept payments");
        }
        if amount_cents < 1 || amount_cents > merchant.input.limits.single_payment_cents { return Err("invalid amount"); }
        self.payments.insert(reference.into(), Payment { merchant_reference: merchant_reference.into(),
            amount_cents, refunded_cents: 0, is_captured: false });
        self.emit("payment.authorized", reference);
        Ok(())
    }

    fn post(&mut self, reference: &str, account: &str, kind: &'static str, amount_cents: i64) {
        for (account, amount_cents) in [(account, amount_cents), ("clearing", -amount_cents)] {
            self.ledger.push(LedgerEntry { reference: reference.into(), account: account.into(), kind, amount_cents });
        }
    }

    fn balance(&self, account: &str) -> i64 {
        self.ledger.iter().filter(|entry| entry.account == account).map(|entry| entry.amount_cents).sum()
    }

    fn capture(&mut self, reference: &str) -> ServiceResult<()> {
        let payment = self.payments.get_mut(reference).ok_or("unknown payment")?;
        if payment.is_captured { return Ok(()); }
        payment.is_captured = true;
        let account = payment.merchant_reference.clone();
        let amount_cents = payment.amount_cents;
        self.post(reference, &account, "capture", amount_cents);
        self.emit("payment.captured", reference);
        Ok(())
    }

    fn refund(&mut self, reference: &str, amount_cents: i64) -> ServiceResult<()> {
        let payment = self.payments.get(reference).ok_or("unknown payment")?;
        let account = payment.merchant_reference.clone();
        if !payment.is_captured || !self.merchants[&account].input.capabilities.can_issue_refunds {
            return Err("refund disabled");
        }
        if amount_cents < 1 || amount_cents > payment.amount_cents - payment.refunded_cents
            || amount_cents > self.balance(&account) { return Err("refund exceeds funds"); }
        self.payments.get_mut(reference).unwrap().refunded_cents += amount_cents;
        self.post(reference, &account, "refund", -amount_cents);
        self.emit("payment.refunded", reference);
        Ok(())
    }

    fn payout(&mut self, reference: &str, amount_cents: i64) -> ServiceResult<()> {
        let merchant = self.merchants.get(reference).ok_or("unknown merchant")?;
        if merchant.status != MerchantStatus::Active || !merchant.input.capabilities.can_request_payouts {
            return Err("payout disabled");
        }
        if amount_cents < 1 || amount_cents > self.balance(reference) { return Err("insufficient funds"); }
        self.post(reference, reference, "payout", -amount_cents);
        self.emit("payout.completed", reference);
        Ok(())
    }

    fn export(&self) -> ServiceResult<String> {
        if !self.tenant.is_export_enabled { return Err("export disabled"); }
        let mut lines = vec!["reference,country,city,document,value".to_string()];
        for (reference, merchant) in &self.merchants {
            for (field, value) in merchant.input.identifiers.fields() {
                let cells = [reference.as_str(), merchant.input.country, merchant.input.address.city, field, value];
                lines.push(cells.iter().map(|value| format!("\"{}\"", value.replace('"', "\"\""))).collect::<Vec<_>>().join(","));
            }
        }
        Ok(lines.join("\n"))
    }

    fn marketing_recipients(&self) -> Vec<&str> {
        self.merchants.iter().filter(|(_, merchant)| merchant.input.preferences.has_marketing_consent)
            .map(|(reference, _)| reference.as_str()).collect()
    }
}

#[derive(Default)]
struct Checks { assertions: usize }
impl Checks {
    fn that(&mut self, condition: bool, message: &str) {
        self.assertions += 1;
        assert!(condition, "{message}");
    }
}

fn run_scenario(scenario: &Scenario, checks: &mut Checks) -> (usize, usize) {
    let mut service = MerchantService::new(&scenario.tenant).expect("valid tenant");
    checks.that(service.verify(&scenario.verification).is_ok(), "verification rejected");
    checks.that(service.verification.as_ref() == Some(&scenario.verification), "verification changed");
    let mut documents = 0;
    for (index, input) in scenario.merchants.iter().enumerate() {
        let reference = input.external_reference;
        checks.that(service.register(input).is_ok(), "registration failed");
        checks.that(service.register(input).is_err(), "duplicate registration accepted");
        for (field, value) in input.identifiers.fields() {
            checks.that(service.merchants[reference].input.identifiers.fields().contains(&(field, value)), "stored document changed");
            documents += 1;
        }
        let payment = format!("payment-{index}");
        checks.that(service.authorize(&payment, reference, scenario.payment_amount_cents).is_err(), "draft accepted payment");
        checks.that(service.submit(reference).is_ok(), "submission failed");
        checks.that(service.approve(reference, "reviewer-a").is_ok(), "review failed");
        if input.capabilities.should_require_second_reviewer {
            checks.that(service.merchants[reference].status == MerchantStatus::Review, "second review bypassed");
            checks.that(service.approve(reference, "reviewer-a").is_err(), "same reviewer accepted twice");
            checks.that(service.approve(reference, "reviewer-b").is_ok(), "second review failed");
        }
        checks.that(service.merchants[reference].status == MerchantStatus::Active, "merchant not active");
        checks.that(service.authorize(&payment, reference, scenario.payment_amount_cents).is_ok(), "authorization failed");
        checks.that(service.authorize(&payment, reference, scenario.payment_amount_cents).is_ok(), "retry failed");
        checks.that(service.authorize(&payment, reference, scenario.payment_amount_cents + 1).is_err(), "conflicting retry accepted");
        checks.that(service.capture(&payment).is_ok(), "capture failed");
        checks.that(service.capture(&payment).is_ok(), "capture retry failed");
        checks.that(service.balance(reference) == scenario.payment_amount_cents, "capture duplicated");
        checks.that(service.refund(&payment, scenario.partial_refund_cents).is_ok(), "refund failed");
        checks.that(service.payout(reference, scenario.payout_amount_cents).is_ok(), "payout failed");
        let balance = scenario.payment_amount_cents - scenario.partial_refund_cents - scenario.payout_amount_cents;
        checks.that(service.balance(reference) == balance, "balance mismatch");
        checks.that(service.payout(reference, balance + 1).is_err(), "overdraft accepted");
        checks.that(service.balance(reference) == balance, "failed payout changed balance");
    }
    checks.that(service.merchants.len() == scenario.expected_merchant_count, "missing merchants");
    checks.that(documents == scenario.expected_document_count, "missing documents");
    checks.that(service.ledger.iter().map(|entry| entry.amount_cents).sum::<i64>() == 0, "ledger not balanced");
    for entry in &service.ledger { checks.that(!entry.kind.is_empty() && !entry.reference.is_empty(), "ledger metadata missing"); }
    let export = service.export().expect("authorized export");
    checks.that(export.lines().count() == documents + 1, "export row count changed");
    for input in &scenario.merchants {
        for (_, value) in input.identifiers.fields() { checks.that(export.contains(value), "export changed document"); }
    }
    checks.that(service.marketing_recipients().is_empty(), "marketing consent ignored");
    for (index, event) in service.events.iter().enumerate() {
        checks.that(event.sequence == index + 1 && !event.kind.is_empty() && !event.reference.is_empty(), "invalid audit event");
    }
    (service.merchants.len(), documents)
}

fn main() {
    let (timeout_ms, batch_size, checksum_algorithm) = (10000, 5000, "sha256");
    let mut checks = Checks::default();
    checks.that(timeout_ms > batch_size && checksum_algorithm == "sha256", "configuration changed");
    let scenarios = build_scenarios();
    let (mut merchants, mut documents) = (0, 0);
    for scenario in &scenarios {
        let counts = run_scenario(scenario, &mut checks);
        merchants += counts.0;
        documents += counts.1;
    }
    println!("{{\"scenarios\":{},\"merchants\":{},\"documents\":{},\"assertions\":{}}}", scenarios.len(), merchants, documents, checks.assertions);
}

